const schema = JSON.stringify({type:'object',properties:{workstream:{type:'string'},observations:{type:'array',items:{type:'object',properties:{claim:{type:'string'},path:{type:'string'},lines:{type:'string'},evidence:{type:'string'}},required:['claim','path','lines','evidence']}},tests:{type:'array',items:{type:'string'}},gaps:{type:'array',items:{type:'string'}},recommendations:{type:'array',items:{type:'string'}},confidence_notes:{type:'array',items:{type:'string'}}},required:['workstream','observations','tests','gaps','recommendations','confidence_notes']});
const tasks = [
{title:'Trace interaction and provider flow', brief:'Audit Discord interaction and generation flow', scope:'Read only: inspect current message/event entry points, routing and intent/autonomy, utils/generation.py, provider dispatch/implementations, search, response processing and Discord send. Trace one real message path from event to response; capture responsible functions, data handoffs, Discord/provider coupling, relevant tests, failure/visibility gaps. Return only confirmed facts with exact repository-relative paths and line ranges where practical, then implications/recommendations. Do not edit or create files.'},
{title:'Audit context and memory systems', brief:'Audit context, memory, identity, and RAG', scope:'Read only: inspect PromptBuilder/ContextProvider implementations, conversation manager, user and character memory, canon, persona/identity, knowledge base and RAG retrieval. Confirm scope, retrieval/injection behavior, deletion/correction/retention where implemented, tests, and boundaries. Return exact repository-relative paths and line ranges where practical; distinguish confirmed behavior from recommendations. Do not edit or create files.'},
{title:'Audit API runtime and configuration boundary', brief:'Audit API, module loading, and configuration', scope:'Read only: inspect FastAPI endpoints, startup/lifecycle, module loading, config schema/access patterns on generation path, provider interface setup, and any runtime boundary relevant to eventual Discord adapter -> reusable Freesona runtime. Identify current behavior, Discord coupling, likely smallest seam and migration steps, evidence paths/lines, tests and risks. Do not edit or create files.'},
{title:'Audit tests and observability', brief:'Audit tests, logs, and interaction observability', scope:'Read only: inspect tests across interaction/context/provider/API areas, current logging and any metrics/tracing/diagnostics. Determine what an operator can establish for a single interaction: participation decision, selected contexts/memories, tools/capabilities, provider/model, stage/total latency, errors. Include privacy risks of adding instrumentation, an appropriate smallest instrumentation increment, evidence paths/lines and tests. Do not edit or create files.'}
];
const mapped = await parallel('Read-only Week 1 repository audit', () => tasks.map(t => agent('Repository: E:\\Documents\\Yanami (the active local Freesona checkout). Inspect the current source directly; do not rely on prior summaries. If the local checkout is inaccessible in your environment, report that clearly and do not guess. Read AGENTS.md first. Preserve existing working-tree changes. No edits, no file creation, no formatter/test commands that write artifacts.\n\nTask: '+t.scope+'\n\nOutput a concise, evidence-grounded result matching the required JSON schema. Keep observations separate from recommendations. For every material repository claim include repository-relative file path and line range; cite tests by path. Include only your assigned area and explicit cross-boundary facts.',{brief:t.brief,schema, sandbox:'shared', effort_level:'standard'})), {schema});
const ok = mapped.filter(r=>r.ok).map(r=>r.value);
const failures = mapped.map((r,i)=>r.ok?null:{workstream:tasks[i].title,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducedSchema = JSON.stringify({type:'object',properties:{report_markdown:{type:'string'},key_conclusion:{type:'string'},limitations:{type:'array',items:{type:'string'}}},required:['report_markdown','key_conclusion','limitations']});
const reduced = await agent('Synthesize one concise but substantive Week 1 baseline report from these independent repository audit results. Do not add unsupported claims or pretend failed/inaccessible workstreams succeeded. Label confirmed observations vs recommendations and cite exact files/line ranges from the input. Use exactly these sections: 1. Current interaction pipeline; 2. Confirmed strengths; 3. Confirmed remaining problems; 4. Recommended runtime seam; 5. MUST CHANGE NOW; 6. SHOULD CHANGE SOON; 7. CAN WAIT; 8. Next-milestone acceptance criteria; 9. Risks and dependencies; 10. Repository changes recommended for Week 1. Clearly say whether source code changes are warranted now. Acceptance criteria must specify scenario, selected context, excluded context, expected provider request, and test/demo. Keep recommendations minimal, behavior-linked, and consistent with no broad rewrite. Inputs follow as JSON: '+JSON.stringify({results:ok,failures}),{brief:'Synthesize evidence into Week 1 baseline report',schema:reducedSchema,sandbox:'shared',effort_level:'standard'});
return {results:ok,failures,reducer:reduced.ok?reduced.value:{error:reduced.error}};

